  SELECT string_agg(g.id::text, ', ') INTO bad FROM g
   WHERE NOT EXISTS (SELECT 1 FROM player_facts f WHERE f.id = g.id AND f.player_name = g.player_name AND f.sport = g.sport
                       AND f.fact_type = g.fact_type AND f.fact_value = g.fact_value AND (f.player_id IS NOT NULL) = g.owned);
  IF bad IS NOT NULL THEN RAISE EXCEPTION '019b: rows changed: %. Nothing changed.', bad; END IF;
  SELECT count(*) INTO n FROM backup_20260928_junk_players_019b; IF n <> 6 THEN RAISE EXCEPTION '019b: expected 6 junk players, found %', n; END IF;
  SELECT count(*) INTO n FROM player_facts f JOIN backup_20260928_junk_players_019b p ON p.id = f.player_id;
  IF n <> 6 THEN RAISE EXCEPTION '019b: the junk players own % facts, expected 6. Nothing changed.', n; END IF;
  SELECT count(*) INTO n FROM answer_submissions s JOIN backup_20260928_junk_players_019b p ON p.id = s.player_id;
  IF n > 0 THEN RAISE EXCEPTION '019b: % answers reference a junk player. Nothing changed.', n; END IF;
  SELECT count(*) INTO n FROM moves m JOIN backup_20260928_junk_players_019b p ON p.id IN (m.p1_player_id, m.p2_player_id);
  IF n > 0 THEN RAISE EXCEPTION '019b: % moves reference a junk player. Nothing changed.', n; END IF;

  DELETE FROM player_facts f USING backup_20260928_junk_facts_019b b WHERE f.id = b.id;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 533 THEN RAISE EXCEPTION '019b: expected 533 facts deleted, got %', n; END IF;
  DELETE FROM player_aliases a USING backup_20260928_junk_aliases_019b b WHERE a.id = b.id;
  DELETE FROM players p USING backup_20260928_junk_players_019b b WHERE p.id = b.id;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 6 THEN RAISE EXCEPTION '019b: expected 6 players deleted, got %', n; END IF;
END
$mig$;

COMMIT;

-- --- CHECKS (run after COMMIT; one row; permanent tables only) -------------------------------------
SELECT
  (SELECT count(*) FROM backup_20260928_junk_facts_019b)                                              AS facts_removed,
  (SELECT count(*) FROM backup_20260928_junk_players_019b)                                            AS players_removed,
  (SELECT count(*) FROM backup_20260928_junk_aliases_019b)                                            AS aliases_removed,
  (SELECT count(*) FROM player_facts f JOIN backup_20260928_junk_facts_019b b ON b.id = f.id)         AS facts_still_present,
  (SELECT count(*) FROM players p JOIN backup_20260928_junk_players_019b b ON b.id = p.id)            AS players_still_present,
  (SELECT bool_and(relrowsecurity) FROM pg_class WHERE relname IN ('backup_20260928_junk_facts_019b', 'backup_20260928_junk_players_019b', 'backup_20260928_junk_aliases_019b')) AS backup_rls,
  (SELECT count(*) FROM information_schema.role_table_grants WHERE table_name IN ('backup_20260928_junk_facts_019b', 'backup_20260928_junk_players_019b', 'backup_20260928_junk_aliases_019b')
     AND grantee IN ('anon', 'authenticated'))                                                        AS backup_browser_grants,
  (SELECT coalesce(string_agg(sport || ' ' || n, ', ' ORDER BY sport), 'none') FROM (
     SELECT ps.sport, count(*) AS n FROM (SELECT DISTINCT player_id, sport FROM player_facts WHERE player_id IS NOT NULL) ps
      WHERE NOT EXISTS (SELECT 1 FROM player_pageviews v WHERE v.player_id = ps.player_id AND v.sport = ps.sport)
      GROUP BY ps.sport) m) AS players_without_estimate_by_sport;
-- EXPECTED: facts_removed = 533; players_removed = 6; aliases_removed = 16; facts_still_present = 0; players_still_present = 0; backup_rls = true; backup_browser_grants = 0; players_without_estimate_by_sport = none

